select t.*,(select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'APPROVAL_TYPE' and sc.code_value = t.condition_type)condition_type_n from prj_approval_condition t, prj_project_approval a
1=1 and t.approval_id = a.approval_id and a.data_class = 'NORMAL' -- and t.APPROVAL_ID = nvl( -- ( -- SELECT -- aa.approval_id -- FROM -- prj_project_approval aa -- WHERE -- aa.data_class = 'NORMAL' -- AND aa.project_id = t.project_id -- ) ,- 99 -- )
and t.project_id = #{projectId}
and t.APPROVAL_ID = #{approvalId}
and t.approval_type = #{approvalType}

select t.*,(select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'APPROVAL_TYPE' and sc.code_value = t.condition_type)condition_type_n from prj_approval_condition t, prj_project_approval a
1=1 and t.approval_id = a.approval_id and a.data_class = 'CHANGE' -- and t.APPROVAL_ID = nvl( -- ( -- SELECT -- aa.approval_id -- FROM -- prj_project_approval aa -- WHERE -- aa.data_class = 'NORMAL' -- AND aa.project_id = t.project_id -- ) ,- 99 -- )
and t.project_id = #{projectId}
and t.APPROVAL_ID = #{approvalId}
and t.approval_type = #{approvalType}

select t.*,(select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'APPROVAL_TYPE' and sc.code_value = t.condition_type)condition_type_n from prj_approval_condition t, prj_project_approval a
1=1 and t.approval_id = a.approval_id and a.data_class = 'NORMAL' and t.APPROVAL_TYPE = 'BEFORE'
and t.approval_id = #{approvalId}

select t.APPROVAL_RECORD_ID, t.PROJECT_ID,t.APPROVAL_ID,t.APPROVAL_SEQ,t.CONDITION_CONTENT from prj_approval_condition t, prj_project_approval a
1=1 and t.approval_id = a.approval_id and a.data_class = 'NORMAL' and t.APPROVAL_TYPE = 'AFTER'
and t.approval_id = #{approvalId}
